def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg}

    # The connected multicolor shape is the stamp; separate colored cells are anchors.
    components = []
    unseen = set(cells)
    while unseen:
        start = unseen.pop()
        component = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for pos in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                if pos in unseen:
                    unseen.remove(pos)
                    component.add(pos)
                    stack.append(pos)
        components.append(component)

    stamp = max(components, key=len)
    r0 = min(r for r, c in stamp)
    r1 = max(r for r, c in stamp)
    c0 = min(c for r, c in stamp)
    c1 = max(c for r, c in stamp)
    anchor_r, anchor_c = (r0 + r1) // 2, (c0 + c1) // 2
    pattern = [(r - anchor_r, c - anchor_c, grid[r][c]) for r, c in stamp]

    out = [row[:] for row in grid]
    for mr, mc in cells - stamp:
        for dr, dc, value in pattern:
            rr, cc = mr + dr, mc + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = value
    return out
